const app=document.querySelector('#app');
const apiBase=(app?.dataset.apiBase||'').replace(/\/$/,'');
const icons={home:'⌂',path:'◎',explore:'✧',skills:'❖',projects:'▦',internships:'▣',jobs:'♧',notifications:'♧',profile:'◉',users:'♙',courses:'⌘',reports:'▥',settings:'⚙'};
const roadmap=window.NEXT_DREAMS_DATA.roadmap;
let careers=window.NEXT_DREAMS_DATA.careers;
let catalogSourceStatus="Local sample catalog";
let catalogRequestVersion=0, catalogRequestKey="", catalogPage=1, catalogTotal=null, catalogDebounceTimer;
const catalogPageSize=24;
const streams=window.NEXT_DREAMS_DATA.streams;
const pathways=window.NEXT_DREAMS_DATA.pathways;
const pathStages=window.NEXT_DREAMS_DATA.pathStages;
const pathwayEngine=window.NEXT_DREAMS_PATHWAY_ENGINE;
const nav=[['home','Dashboard'],['path','My Career Path'],['explore','Explore Careers'],['skills','Skills & Learning'],['projects','Projects'],['internships','Internships'],['jobs','Jobs & Higher Studies'],['notifications','Notifications'],['profile','Profile']];
let activeRoles=[],adminCareerRows=[];
let page=new URLSearchParams(location.search).get('reset')==='1'||new URLSearchParams(location.hash.slice(1)).get('type')==='recovery'?'reset':'landing',search='',pathFilter='All paths',admin=false,toastTimer,selectedCareer='Cybersecurity',selectedGraphNode='',activeSession=null;let completed=JSON.parse(localStorage.getItem('nd-completed')||'[]');
function toast(msg){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.append(el)}el.textContent=msg;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),2600)}
function brand(){return `<div class="brand"><span class="brand-icon">➤</span><span>Next <b>Dreams</b></span></div>`}
function topNav(){return `<header class="top-nav">${brand()}<nav class="nav-links"><button class="active" data-go="landing">Home</button><button data-go="explore">Explore</button><button data-go="about">About</button><button data-go="roadmap">Resources</button><button data-go="contact">Contact</button></nav><div class="nav-actions"><button class="btn outline" data-go="signin">Sign In</button><button class="btn" data-go="signup">Sign Up</button></div></header>`}
function scene(){return `<div class="dream-scene" aria-label="A student looking toward a city and future opportunities"><div class="sun"></div><div class="skyline"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="path-art"></div><div class="traveler"><i class="head"></i><i class="body"></i><i class="pack"></i></div><div class="signpost"><span>Engineering</span><span>Design</span><span>Data science</span></div><div class="scribble">Your future starts here ✦</div></div>`}
function graphRows(routes){return routes.map(route=>`<div class="path-route-row" data-route-id="${route.id}">${route.steps.map((step,index)=>`<button class="path-node ${selectedGraphNode===step?'selected':''}" type="button" data-action="graph-node" data-graph-node="${step}" aria-pressed="${selectedGraphNode===step}"><small>${pathStages[index]}</small><b>${step}</b></button>`).join('')}</div>`).join('')}
function treeBranch(branch){return `<li class="tree-branch"><button class="tree-step" type="button" data-action="tree-node" data-name="${branch.title}"><span>${branch.title}</span><small>${branch.detail||'Explore options and requirements'}</small></button><ul>${(branch.children||[]).map(child=>`<li class="tree-leaf"><button class="tree-step tree-step-leaf" type="button" data-action="tree-node" data-name="${child.title}"><span>${child.title}</span></button><div class="tree-careers">${child.careers.map(name=>`<button class="tree-career" data-action="career" data-name="${name}">${name} ↗</button>`).join('')}</div></li>`).join('')}</ul></li>`}
function graphMarkup(){return `<section class="section" id="pathways"><div class="section-title"><small>YOUR JOURNEY HAS MANY BRANCHES</small><h2>See where each step can lead</h2><p class="muted">Start from your current education stage, compare routes, then open a career to see skills and next steps. Eligibility varies by course, board, institution and current notice.</p></div><div class="education-tree">${window.NEXT_DREAMS_DATA.educationTree.map(stage=>`<article class="tree-stage"><header class="tree-stage-head"><span class="tree-stage-kicker">START HERE</span><h3>${stage.title}</h3><p>${stage.subtitle}</p></header><ul class="tree-root">${stage.branches.map(treeBranch).join('')}</ul></article>`).join('')}</div><div class="tree-footnote"><strong>Use this as a discovery map.</strong> Course names and example careers are illustrative. It does not determine admission eligibility; verify current rules with the relevant board, institution, regulator or recruitment authority. <span>${careers.length} catalog options</span></div><div class="path-map-actions"><button class="btn" data-go="explore">Browse the career catalog →</button><button class="btn outline" data-go="backtest">Simulate route options</button></div></section>`}
function landing(){return `${topNav()}<main><section class="hero"><div><span class="eyebrow">✦ &nbsp; Plan Today → Build Tomorrow</span><h1>Find Your Path.<br>Build Your <span class="gradient">Next Dreams.</span></h1><p>Explore career options, understand educational pathways, build skills, find projects and prepare for what comes next — all in one place.</p><div class="hero-actions"><button class="btn" data-go="explore">Explore Career Paths →</button><button class="btn outline" data-go="about">Learn More</button></div><div class="stats"><div class="stat"><span class="icon-bubble">◈</span><span><strong>${careers.length}+</strong>Career catalog options</span></div><div class="stat"><span class="icon-bubble">▤</span><span><strong>3</strong>Education starting stages</span></div><div class="stat"><span class="icon-bubble">▣</span><span><strong>Search + filter</strong>Explore by stream and field</span></div></div></div>${scene()}</section>${graphMarkup()}<section class="section" id="about"><div class="section-title"><small>WHY CHOOSE NEXT DREAMS</small><h2>Everything you need for a brighter future</h2><p class="muted">From Class 10 to your dream job, explore connected study and career options.</p></div><div class="feature-grid">${[['◈','Explore Career Paths','Compare routes after Class 10, Intermediate and graduation.'],['▤','Get Roadmaps','Follow a step-by-step learning path.'],['⚙','Build Skills','Learn practical and transferable skills.'],['⌘','Work on Projects','Practice through projects for your current stage.'],['▣','Find Opportunities','Explore internships and further study routes.'],['↗','Track Your Growth','Save progress and choose a next step.']].map(item=>`<article class="feature"><span class="icon-bubble">${item[0]}</span><h3>${item[1]}</h3><p>${item[2]}</p><button class="plain" data-go="explore" aria-label="Explore ${item[1]}">→</button></article>`).join('')}</div></section></main><footer class="footer" id="contact">${brand()}<span>Choose your path. Know your roadmap. Build your career.</span><button class="btn small" data-go="signup">Get Started →</button></footer>`}
function auth(type){let signup=type==='signup',forgot=type==='forgot';return `${topNav()}<main class="auth-wrap"><section class="auth-copy"><span class="eyebrow">✦ &nbsp; ${forgot?'Secure your account':signup?'Your future, our guidance':'Welcome back!'}</span><h1>${forgot?'Forgot your':signup?'Create your account and':'Your next dream'}<br><span class="gradient">${forgot?'Password?':'journey starts here'}</span></h1><p>${forgot?'Enter your email address and we will request a secure reset link.':signup?'Explore educational pathways, discover opportunities and build the future you dream about.':'Sign in to continue your journey towards a brighter future.'}</p><div class="auth-illustration">🎒</div><div class="auth-features"><span>✦ Personalized recommendations</span><span>▤ Career roadmaps</span><span>♡ Always here to help</span></div></section><form class="auth-card" id="auth-form"><div class="icon-bubble" style="margin:auto">${forgot?'✉':signup?'♙':'➤'}</div><h2>${forgot?'Reset your password':signup?'Create your account':'Sign in'}</h2><p>${forgot?'We will help you get back to your journey.':signup?'Take the first step towards your dream career.':'Welcome back! Enter your credentials to continue.'}</p>${signup?'<div class="field"><input required placeholder="Full name" autocomplete="name"></div>':''}<div class="field"><input required type="email" placeholder="Email address" autocomplete="email"></div>${!forgot?'<div class="field"><input required type="password" minlength="8" placeholder="Password (at least 8 characters)" autocomplete="current-password"></div>':''}${signup?'<label class="muted">Account type</label><div class="role-options"><button type="button" class="selected">Student</button></div>':''}<button class="btn" type="submit">${forgot?'Send reset link':signup?'Create account':'Sign in'} &nbsp; →</button><div class="auth-note">${forgot?'<button class="plain" type="button" data-go="signin">← Back to Sign In</button>':signup?'By creating an account, you agree to our Terms and Privacy Policy.':'<button class="plain" type="button" data-go="forgot">Forgot password?</button><br><br>New here? <button class="plain" type="button" data-go="signup">Create an account</button>'}</div><div class="auth-note">${apiBase?'Secure API connection configured.':'API connection is not configured; authentication is unavailable.'}</div></form></main>`}
function sidebar(){let options=admin?[['home','Dashboard'],['users','Users'],['internships','Internships'],['jobs','Jobs & Opportunities'],['courses','Courses & Learning'],['projects','Projects'],['reports','Reports'],['settings','Settings']]:nav;return `<aside class="sidebar" id="sidebar">${brand()}<div class="side-label">${admin?'ADMINISTRATION':'STUDENT SPACE'}</div>${options.map(([id,label])=>`<button class="side-link ${page===id?'active':''}" data-page="${id}"><i>${icons[id]||'◉'}</i>${label}${id==='notifications'&&!admin?'<span class="pill" style="margin-left:auto">3</span>':''}</button>`).join('')}<div class="sidebar-bottom"><div style="font-size:35px">🚀</div><strong>${admin?'Better dreams.':'Keep going!'}</strong><br>${admin?'Admin demo view':'Your dream is closer than you think.'}<br><button class="plain" data-action="switch-role" style="color:#aebeff;margin-top:9px;font-size:11px">${admin?'Switch to student':'Open admin demo'}</button></div></aside>`}
function shell(content){return `<div class="app-shell">${sidebar()}<div class="work-area"><header class="app-top"><button class="mobile-toggle" data-action="menu" aria-label="Open navigation">☰</button><label class="searchbox">⌕ <input id="global-search" placeholder="Search careers, skills, courses..." value="${search}"></label><span class="top-spacer"></span><button class="plain" data-page="notifications" aria-label="Notifications">♧ <sup style="color:#f23b4c">3</sup></button><div class="user-menu"><span class="avatar">${admin?'🧑🏻‍💼':'👩🏻‍🎓'}</span><span class="user-label"><b>${admin?'Admin':'Sai Chandana'}</b><br><span class="muted">${admin?'System administrator':'Student'}</span></span><button class="plain" data-action="account">⌄</button></div></header><main class="content">${content}</main></div></div>`}
function track(){let steps=[['Class 10','Completed','✿'],['Stream','MPC','❖'],['Intermediate','Next','▦'],['Degree','B.Tech','▣'],['Branch','CSE','⌘'],['Specialization','Cybersecurity','⬡']];return `<section class="panel track-panel"><div class="panel-head"><h2>Your career path</h2><button class="text-link" data-page="path">View full roadmap →</button></div><div class="career-track">${steps.map((s,i)=>`<div class="track-step"><div class="icon-bubble">${s[2]}</div><b>${s[0]}</b><span>${s[1]}</span></div>`).join('')}</div></section>`}
function home(){return `<div class="welcome"><div><h1>Hello, Sai Chandana! 👋</h1><p>Here’s a small step towards your dream career today.</p></div><button class="btn small" data-page="explore">Explore paths →</button></div><div class="dashboard-grid"><div class="main-stack"><section class="banner"><h2>Big dreams. Better future.</h2><p>Explore your career path and build skills at a pace that works for you.</p><button class="btn small" data-page="path">Continue your roadmap →</button><span class="banner-art">🪁</span></section><div class="quick-grid">${[['◈','Explore Careers','Discover your options','explore'],['▤','My Roadmap','View your plan','path'],['⚙','Skills & Learning','Build your skills','skills'],['▣','Find Opportunities','Explore next steps','jobs']].map(x=>`<button class="quick-card plain" data-page="${x[3]}" style="text-align:left"><span class="icon-bubble">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]} →</p></button>`).join('')}</div>${track()}<div class="lower-grid"><section class="panel"><div class="panel-head"><h3>Recommended for you</h3><button class="text-link" data-page="explore">View all →</button></div>${careers.slice(0,8).map(c=>`<div class="list-row"><span class="icon-bubble">◈</span><div class="grow"><b>${c.name}</b><div class="muted">Explore subjects, skills and projects</div></div><button class="plain" data-action="career" data-name="${c.name}">→</button></div>`).join('')}</section><section class="panel"><div class="panel-head"><h3>Your skills progress</h3><button class="text-link" data-page="skills">View all →</button></div><div class="progress-wrap"><div class="donut"><b>6/10<br><small class="muted">Skills</small></b></div><div class="skill-bars" style="flex:1"><span>Technical skills</span><b>4/6</b><span>Soft skills</span><b>2/4</b><span>Domain skills</span><b>1/4</b></div></div><div class="muted" style="margin-top:15px">Mark a skill complete to update your progress.</div></section></div></div><div class="right-stack"><section class="panel"><div class="panel-head"><h3>Your profile</h3><button class="text-link" data-page="profile">Edit →</button></div><div class="progress-wrap"><span class="icon-bubble" style="width:60px;height:60px;font-size:26px">♙</span><div style="flex:1"><b>Profile progress</b><div class="bar"><i style="width:65%"></i></div><div class="muted">65% complete</div></div></div></section><section class="panel"><div class="panel-head"><h3>Recent notifications</h3><button class="text-link" data-page="notifications">View all →</button></div>${[['✧','Opportunity research checklist','Added to your roadmap'],['▣','Roadmap ready to explore','Cybersecurity · Year 1'],['◈','Skills to try next','Linux foundations']].map(n=>`<div class="notification"><span class="icon-bubble">${n[0]}</span><div><b>${n[1]}</b><div class="muted">${n[2]}</div><div class="muted">For your planning</div></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h3>Upcoming steps</h3><button class="text-link" data-page="jobs">View all →</button></div>${[['APR','Research entrance exams','Explore official sources'],['MAY','Start a small project','Portfolio preparation'],['JUN','Look for internships','Availability varies']].map(n=>`<div class="event-row"><div class="date-chip">${n[0]}</div><div><b>${n[1]}</b><div class="muted">${n[2]}</div></div></div>`).join('')}</section></div></div>`}
function careerHasEntryStage(careerName,stageName){const stage=window.NEXT_DREAMS_DATA.educationTree.find(item=>item.title===stageName);return Boolean(stage?.branches.some(branch=>branch.children.some(child=>child.careers.includes(careerName))))}
function explore(){const query=search.trim().toLowerCase();const subset=careers.filter(c=>{const haystack=[c.name,c.category,c.course,c.minimumEducation,c.role,...(c.tags||[]),...(c.eligibleStreams||[])].join(' ').toLowerCase();const searchMatch=!query||haystack.includes(query);const filterMatch=pathFilter==='All paths'||(pathFilter==='After Class 10'?careerHasEntryStage(c.name,'After Class 10'):pathFilter==='Intermediate'?careerHasEntryStage(c.name,'After Class 12 / Intermediate'):pathFilter==='Graduation'?careerHasEntryStage(c.name,'After Graduation'):pathFilter==='Technology'?/computer science|engineering|technology|science/i.test(c.category||''):pathFilter==='Healthcare'?/health|medical|life sciences/i.test(c.category||''):pathFilter==='Commerce'?/commerce|business|finance/i.test(c.category||''):pathFilter==='Vocational education'?/vocational|trade|skilled/i.test(c.category||''):(c.category||'').toLowerCase().includes(pathFilter.toLowerCase())||(c.eligibleStreams||[]).some(x=>x.toLowerCase()===pathFilter.toLowerCase()));return searchMatch&&filterMatch});const pageCount=catalogTotal===null?1:Math.max(1,Math.ceil(catalogTotal/catalogPageSize));return `<div class="page-toolbar"><div><h1>Explore career opportunities</h1><p class="muted">Search across a growing catalog. Each option includes a starting education route and stream notes where available.</p></div><span class="pill">${catalogTotal===null?subset.length:catalogTotal} matching options · ${catalogSourceStatus}</span></div><div class="filters">${['All paths','After Class 10','Intermediate','Graduation','Technology','Healthcare','Commerce','Law and public service','Creative industries','Vocational education','MPC','BiPC','MEC','CEC','Humanities','Arts'].map(x=>`<button class="filter ${pathFilter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><section class="panel catalog-search"><label class="searchbox" style="width:100%">⌕ <input id="career-search" aria-label="Search career catalog" placeholder="Search titles, skills, streams or roles" value="${search}"></label><p class="muted">Filter by education route, field or stream. Catalog entries are for exploration, not individual eligibility decisions.</p></section>${subset.length?`<div class="catalog-grid">${subset.map(c=>`<article class="career-card"><div class="career-card-top"><span class="career-category">${c.category||'Career exploration'}</span><span class="career-icon">✦</span></div><span class="record-status ${c.sourceStatus==='verified'?'verified':'draft'}">${c.sourceStatus==='verified'?'Sources reviewed':'Needs source review'}</span><h2>${c.name}</h2><p>${c.desc}</p><div class="career-meta"><b>Common starting route</b><span>${c.minimumEducation||c.course}</span></div><div class="career-meta"><b>Streams to explore</b><span>${(c.eligibleStreams||['Varies']).join(' · ')}</span></div><div class="chips">${(c.tags||[]).map(t=>`<span class="chip">${t}</span>`).join('')}</div><button class="text-link career-open" data-action="career" data-name="${c.name}">Explore this path →</button></article>`).join('')}</div>`:'<div class="panel empty-state">No careers match that search and filter. Try a different term or choose All paths.</div>'}${catalogTotal!==null&&pageCount>1?`<nav class="catalog-pagination" aria-label="Career catalog pages"><button class="btn outline small" data-catalog-page="${catalogPage-1}" ${catalogPage<=1?'disabled':''}>← Previous</button><span>Page ${catalogPage} of ${pageCount}</span><button class="btn outline small" data-catalog-page="${catalogPage+1}" ${catalogPage>=pageCount?'disabled':''}>Next →</button></nav>`:''}<div class="catalog-note">${window.NEXT_DREAMS_DATA.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noreferrer">${s.name} ↗</a>`).join(' · ')}<p>Source directory links support general career exploration. Check course-specific eligibility, approvals, admissions and recruitment conditions with the official authority for the current year.</p></div>`}
function pathwayDetail(name=selectedCareer){let c=careers.find(x=>x.name===name)||careers[0];return `<div class="page-toolbar"><div><h1>${c.name} pathway</h1><p class="muted">A connected route from education to skills, practice and next opportunities.</p></div><button class="btn small" data-action="save-path">${localStorage.getItem('nd-saved')?'✓ Saved':'☆ Save pathway'}</button></div><section class="panel"><div class="panel-head"><h2>Your route at a glance</h2><span class="pill">Planning guide</span></div><div class="chips">${['Class 10','Stream','Intermediate',c.course,c.role+' role','Higher studies'].map((x,i)=>`<span class="chip">${i?'→ ':''}${x}</span>`).join('')}</div><p class="muted" style="margin-top:14px">Explore alternative routes too. The examples below are learning suggestions, not admission guarantees.</p></section><div class="roadmap-grid" style="margin-top:16px">${roadmap.map((r,i)=>`<section class="roadmap-card"><h3>${r.year}</h3><div class="muted">Suggested focus · Stage ${i+1}</div>${r.items.map(item=>`<label class="check-row"><input type="checkbox" data-item="${item}" ${completed.includes(item)?'checked':''}>${item}</label>`).join('')}</section>`).join('')}</div><div class="lower-grid" style="margin-top:16px"><section class="panel"><h3>Practice through projects</h3><div class="list-row"><span class="icon-bubble">⌘</span><span class="grow"><b>Personal learning lab</b><div class="muted">Document small experiments and what you learned.</div></span></div><div class="list-row"><span class="icon-bubble">▤</span><span class="grow"><b>Network notes</b><div class="muted">Map basic network concepts as you learn.</div></span></div></section><section class="panel"><h3>Explore opportunities</h3><p class="muted">Browse opportunity categories and verify current requirements with the official provider.</p><button class="btn small" data-page="jobs">View opportunities →</button></section></div>`}
function skillsPage(){let skills=['Programming fundamentals','Networking fundamentals','Linux basics','Operating systems','Databases','Security fundamentals','Communication','Problem solving'];return `<div class="page-toolbar"><div><h1>Skills & learning</h1><p class="muted">Track what you know and choose a useful next skill.</p></div><span class="pill">Beginner → Intermediate → Advanced</span></div><div class="roadmap-grid">${['Technical foundations','Domain learning'].map((title,i)=>`<section class="roadmap-card"><h3>${title}</h3><p class="muted">${i?'Build knowledge after the computing foundations.':'Start with concepts that support many technology routes.'}</p>${skills.slice(i?4:0,i?8:4).map((s,j)=>`<label class="check-row"><input type="checkbox" data-item="${s}" ${completed.includes(s)?'checked':''}><span>${s}<span class="muted" style="display:block">${j===0?'Beginner':j>2?'Intermediate':'Foundations'}</span></span></label>`).join('')}</section>`).join('')}</div><section class="panel" style="margin-top:15px"><h3>Suggested order</h3><div class="chips">${['Programming','Networking','Linux','Security basics','Network security'].map((x,i)=>`<span class="chip">${i?'→ ':''}${x}</span>`).join('')}</div></section>`}

function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function catalogAdminPage(){const canEdit=activeRoles.some(role=>['content_editor','admin'].includes(role));const canVerify=activeRoles.some(role=>['verifier','admin'].includes(role));return `<div class="page-toolbar"><div><h1>Career catalog management</h1><p class="muted">Add and maintain catalog records. Editors save draft content; a verifier checks item-specific official evidence before marking it reviewed.</p></div><span class="pill">Protected staff workspace</span></div>${!activeSession?.access_token?'<section class="panel admin-guard"><h2>Staff sign-in required</h2><p>The admin demo switch does not grant access. Sign in with your Supabase staff account to manage catalog records.</p><button class="btn small" data-go="signin">Sign in →</button></section>':!canEdit&&!canVerify?'<section class="panel admin-guard"><h2>Catalog permissions required</h2><p>This account has no content-editor, verifier or admin role. Ask an administrator to grant the least-privileged role you need.</p></section>':`<div class="catalog-admin-grid">${canEdit?`<form class="panel catalog-admin-form" id="catalog-add-form"><h2>Add a career</h2><p class="muted">New records start as drafts and appear with a source-review label.</p><label>Title<input name="title" required maxlength="160"></label><label>Slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" maxlength="180" placeholder="auto-generated from title"></label><label>Category<input name="category" required maxlength="120"></label><label>Minimum education / entry note<input name="minimum_education" required maxlength="500"></label><label>Summary<textarea name="summary" maxlength="2000" rows="3"></textarea></label><label>Starting stages · comma separated<input name="entry_stages" placeholder="After Class 12 / Intermediate"></label><label>Streams · comma separated<input name="eligible_streams" placeholder="MPC, Any"></label><label>Skills · comma separated<input name="skills"></label><label>Typical roles · comma separated<input name="typical_roles"></label><button class="btn small" type="submit">Save draft career</button><p class="muted" data-form-status aria-live="polite"></p></form>`:''}<section class="panel catalog-admin-list"><div class="panel-head"><h2>Active catalog entries</h2><button class="text-link" data-action="reload-admin-catalog">Refresh →</button></div><div id="admin-catalog-status" class="muted" aria-live="polite">Loading catalog…</div><div id="admin-catalog-rows"></div></section></div>${canEdit?`<dialog id="career-editor" class="career-editor"><form id="catalog-edit-form" method="dialog"><div class="panel-head"><h2>Edit career</h2><button class="plain" value="cancel" aria-label="Close editor">×</button></div><input name="slug" type="hidden"><label>Title<input name="title" required maxlength="160"></label><label>Category<input name="category" required maxlength="120"></label><label>Minimum education<input name="minimum_education" required maxlength="500"></label><label>Summary<textarea name="summary" maxlength="2000" rows="3"></textarea></label><label>Entry stages<input name="entry_stages"></label><label>Streams<input name="eligible_streams"></label><label>Skills<input name="skills"></label><label>Typical roles<input name="typical_roles"></label><button class="btn small" type="submit">Save changes</button></form></dialog>`:''}${canVerify?`<dialog id="career-verifier" class="career-editor"><form id="catalog-verify-form" method="dialog"><div class="panel-head"><h2>Verify sources</h2><button class="plain" value="cancel" aria-label="Close verifier">×</button></div><input name="slug" type="hidden"><p class="muted">Confirm that you checked a current, career-specific official source.</p><label>Source name<input name="source_name" required maxlength="160"></label><label>HTTPS source URL<input name="source_url" required type="url" pattern="https://.*"></label><button class="btn small" type="submit">Record verification</button></form></dialog>`:''}`} `}
async function loadAdminCareerCatalog(){const status=document.querySelector('#admin-catalog-status'),rows=document.querySelector('#admin-catalog-rows');if(!status||!rows)return;status.textContent='Loading the catalog from Supabase…';try{const response=await fetch(`${apiBase}/career-catalog?limit=60`,{headers:activeSession?.access_token?{Authorization:`Bearer ${activeSession.access_token}`}:{},cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.detail||'The career catalog is unavailable.');adminCareerRows=data.items||[];status.textContent=`${data.total} active records · page ${data.page} of ${Math.max(1,Math.ceil(data.total/data.limit))}`;rows.innerHTML=adminCareerRows.map(c=>`<article class="admin-career-row"><div class="grow"><b>${escapeHtml(c.title)}</b><span class="career-category">${escapeHtml(c.category)}</span><span class="record-status ${c.source_status==='verified'?'verified':'draft'}">${escapeHtml(c.source_status)}</span></div>${activeRoles.some(r=>['content_editor','admin'].includes(r))?`<button class="text-link" data-action="edit-catalog-career" data-slug="${escapeHtml(c.slug)}">Edit</button><button class="text-link" data-action="deactivate-catalog-career" data-slug="${escapeHtml(c.slug)}">Deactivate</button>`:''}${activeRoles.some(r=>['verifier','admin'].includes(r))&&c.source_status!=='verified'?`<button class="text-link" data-action="verify-catalog-career" data-slug="${escapeHtml(c.slug)}">Verify source</button>`:''}</article>`).join('')||'<p class="muted">No active catalog records found.</p>'}catch(error){status.textContent=error instanceof Error?error.message:'The catalog could not be loaded.'}}
function splitList(value){return value.split(',').map(item=>item.trim()).filter(Boolean)}
function formCareer(form){const fields=new FormData(form);return {title:String(fields.get('title')||'').trim(),category:String(fields.get('category')||'').trim(),minimum_education:String(fields.get('minimum_education')||'').trim(),summary:String(fields.get('summary')||'').trim(),entry_stages:splitList(String(fields.get('entry_stages')||'')),eligible_streams:splitList(String(fields.get('eligible_streams')||'')),skills:splitList(String(fields.get('skills')||'')),typical_roles:splitList(String(fields.get('typical_roles')||''))}}
function genericPage(){let config={projects:['Projects','Use small projects to apply skills as you learn.',['Personal portfolio','Network mapping notes','Secure login concept','Final-year capstone']],internships:['Internships','Build experience gradually. Availability and requirements change; check the provider’s official listing.',['Explore internship categories','Prepare a project portfolio','Draft a resume','Check official listings']],jobs:['Jobs & higher studies','Explore opportunity types and confirm current eligibility with official sources.',['Private sector roles','Government recruitment','Postgraduate study','Research pathways']],notifications:['Notifications','Planning reminders and saved opportunity updates.',['Review your pathway','Check provider’s official website','Add a portfolio project','Update your learning progress']],profile:['Your profile','Keep your learning goals and education stage up to date.',['Education stage: Intermediate','Interested pathway: Cybersecurity','Learning preference: Hands-on projects','Saved pathway: Cybersecurity']],reports:['Reports','Overview of content quality and review activity.',['Content review queue','Source verification status','Recently updated pathways','Archived material']],users:['Users','Manage people who use the platform. This is a non-privileged demo view.',['Student accounts','Parent accounts','Counsellor accounts','Role permissions']],courses:['Courses & learning','Review courses and related learning pathways.',['B.Tech','B.Sc','B.Com','Diploma / Polytechnic']],settings:['Settings','Application and account preferences.',['Profile settings','Notification preferences','Privacy controls','Sign out']]};let [title,desc,items]=config[page]||config.projects;return `<div class="page-toolbar"><div><h1>${title}</h1><p class="muted">${desc}</p></div>${admin?'<button class="btn small" data-action="add">+ Add item</button>':''}</div><div class="roadmap-grid">${items.map((x,i)=>`<section class="roadmap-card"><div class="panel-head"><h3>${x}</h3>${admin?`<span class="status">${i===0?'Draft':'Needs review'}</span>`:''}</div><p class="muted">${page==='jobs'?'Check the official provider for current details, dates and eligibility before acting.':page==='profile'?'This local demo profile is stored only in your browser session.':'Suggested next step for your career exploration plan.'}</p><button class="text-link" data-action="${page==='profile'?'edit':'details'}">${page==='jobs'?'Review official sources →':'View details →'}</button></section>`).join('')}</div>${page==='jobs'?'<div class="panel" style="margin-top:16px"><b>Dates and eligibility</b><p class="muted">This demo does not claim live availability or student eligibility. Confirm each opportunity against its current official notification.</p></div>':''}`}
function adminHome(){return `<div class="welcome"><div><h1>Welcome, Admin! 👋</h1><p>Manage pathway content and review its source status.</p></div><span class="pill">Admin demo · local only</span></div><div class="admin-metrics">${[['♙','Total users','1,248'],['▣','Internships','320'],['♧','Job categories','186'],['⌘','Courses','142']].map(m=>`<section class="metric"><span class="icon-bubble">${m[0]}</span><div>${m[1]}<strong>${m[2]}</strong><span class="muted">Sample dashboard value</span></div></section>`).join('')}</div><div class="lower-grid" style="grid-template-columns:1.4fr 1fr;margin-top:17px"><section class="panel"><div class="panel-head"><h2>Content review queue</h2><button class="text-link" data-page="reports">View all →</button></div><div class="table-wrap"><table><thead><tr><th>Content</th><th>Type</th><th>Source state</th><th>Action</th></tr></thead><tbody>${[['Cybersecurity year plan','Roadmap','Needs review'],['B.Tech pathway overview','Course route','Draft'],['Internship preparation guide','Guide','Verified'],['Government opportunities','Opportunity','Needs review']].map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td><span class="status">${r[2]}</span></td><td><button class="text-link" data-action="review">Review →</button></td></tr>`).join('')}</tbody></table></div></section><div class="main-stack"><section class="panel"><h3>Data quality</h3><p class="muted">Keep the source date, verification owner and review history with each item.</p><div class="list-row"><span class="pill">Verified</span><span class="grow">Current source recorded</span></div><div class="list-row"><span class="pill" style="background:#fff3dc;color:#bb8018">Stale</span><span class="grow">Review date has passed</span></div><div class="list-row"><span class="pill" style="background:#f2eaff;color:#8649de">Conflicting</span><span class="grow">Sources disagree</span></div></section><section class="panel"><h3>Quick actions</h3><div class="quick-grid" style="grid-template-columns:1fr 1fr;margin-top:12px">${[['Career catalog','catalogAdmin'],['Post internship','internships'],['Add course','courses'],['Review content','reports']].map(x=>`<button class="btn soft small" data-page="${x[1]}">${x[0]}</button>`).join('')}</div></section></div></div>`}
function resetPage(){return auth('signin').replace('<h1>Your next dream<br><span class="gradient">journey starts here</span></h1>','<h1>A fresh start for<br><span class="gradient">your next dream</span></h1>').replace('Sign in to continue your journey towards a brighter future.','Choose a new password to continue your journey.').replace('<h2>Sign in</h2>','<h2>Reset your password</h2>').replace('Welcome back! Enter your credentials to continue.','Enter and confirm your new password.').replace('<div class="field"><input required type="email" placeholder="Email address" autocomplete="email"></div>','').replace('<div class="field"><input required type="password" minlength="6" placeholder="Password" autocomplete="current-password"></div>','<div class="field"><input required type="password" minlength="8" placeholder="New password" autocomplete="new-password"></div><div class="field"><input required type="password" minlength="8" placeholder="Confirm new password" autocomplete="new-password"></div>').replace('Sign in to demo','Save new password').replace('Demo mode: no credentials are sent or stored.','Use the password reset link sent to your email address.')}
function authView(type){return (type==='reset'?resetPage():auth(type)).replace('we will show a demo reset confirmation','we will send a secure reset link if an account matches').replace('We will help you get back to your journey.','Enter your email address and we will send reset instructions if an account matches.').replace('Demo mode: no credentials are sent or stored.','Development mode: account data is sent to the configured API.')}
function backtestPage(){return `${topNav()}<main class="section"><div class="page-toolbar"><div><h1>Pathway simulation</h1><p class="muted">Trace complete routes from the shared career graph using your current stage and interests.</p></div><button class="btn outline" data-go="landing">← Home</button></div><div class="panel"><label class="field">Starting point<select id="backtest-start"><option>Class 10</option><option>Intermediate</option><option>Graduation</option></select></label><label class="field">Interest area<select id="backtest-interest"><option>Not sure yet</option><option>Technology</option><option>Health and science</option><option>Business and finance</option><option>Creative work</option></select></label><button class="btn" data-action="run-backtest">Simulate available routes</button><div id="backtest-result" class="path-map-result" aria-live="polite"><p class="muted">This scenario simulator uses the same illustrative pathway graph as the landing page. It does not use historical admissions outcomes, predict admission, or claim live openings.</p></div></div></main>`}
function debugPage(){return `${topNav()}<main class="section"><div class="page-toolbar"><div><h1>Connection and auth diagnostics</h1><p class="muted">Check configured services and run non-destructive authentication guard probes.</p></div><button class="btn outline" data-go="landing">← Home</button></div><section class="panel"><div class="panel-head"><h2>Service status</h2><button class="btn small" data-action="run-debug">Run service checks</button></div><div id="debug-result" aria-live="polite"><div class="diagnostic-row"><b>Frontend API setting</b><span class="${apiBase?'pill':'status'}">${apiBase?'Configured':'Missing'}</span></div><p class="muted">${apiBase?apiBase:'Set NEXT_PUBLIC_API_BASE_URL in .env.local.'}</p><p class="muted">Credentials remain on the backend and are never displayed here.</p></div></section><section class="panel" style="margin-top:16px"><div class="panel-head"><div><h2>Authentication checks</h2><p class="muted">No accounts are created and no credentials are submitted.</p></div><button class="btn outline small" data-action="run-auth-checks">Run safe auth checks</button></div><div id="auth-debug-result" aria-live="polite"><p class="muted">Checks cover API health, protected-route denial, privileged self-signup denial, request validation, and configured auth status. Live sign-in, recovery, refresh, and role flows need a Supabase project and test accounts.</p></div></section></main>`}
async function loadRemoteCatalog(){if(!apiBase)return;const params=new URLSearchParams({page:String(catalogPage),limit:String(catalogPageSize)});if(search.trim())params.set('q',search.trim());const streams=['MPC','BiPC','MEC','CEC','Humanities','Arts','Vocational'];if(streams.includes(pathFilter))params.set('stream',pathFilter);if(['Technology','Healthcare','Commerce','Law and public service','Creative industries','Vocational education'].includes(pathFilter))params.set('category',pathFilter);if(pathFilter==='After Class 10')params.set('education_level','After Class 10');if(pathFilter==='Intermediate')params.set('education_level','After Class 12 / Intermediate');if(pathFilter==='Graduation')params.set('education_level','After Graduation');const requestKey=params.toString();if(requestKey===catalogRequestKey)return;catalogRequestKey=requestKey;const requestId=++catalogRequestVersion;try{const response=await fetch(`${apiBase}/career-catalog?${requestKey}`,{cache:'no-store',signal:AbortSignal.timeout(4500)});if(!response.ok)throw new Error('Catalog service unavailable');const data=await response.json();if(requestId!==catalogRequestVersion||!Array.isArray(data.items))return;careers=data.items.map(item=>({name:item.title,category:item.category,minimumEducation:item.minimum_education,eligibleStreams:item.eligible_streams||[],educationPathways:item.education_pathways||[],course:item.minimum_education,desc:item.summary,role:(item.typical_roles||[])[0]||'Explore role options',tags:item.skills||[],sourceStatus:item.source_status,sources:item.sources||[]}));catalogTotal=data.total;catalogSourceStatus='Supabase catalog';if(page==='explore')render()}catch{if(requestId===catalogRequestVersion){catalogTotal=null;catalogSourceStatus='Local sample catalog'}}}
function render(){if(['landing','signin','signup','forgot','reset','backtest','debug'].includes(page)){app.innerHTML=page==='landing'?landing():page==='backtest'?backtestPage():page==='debug'?debugPage():authView(page);return}let body=admin&&page==='home'?adminHome():page==='home'?home():page==='explore'?explore():page==='path'?pathwayDetail():page==='skills'?skillsPage():page==='catalogAdmin'?catalogAdminPage():genericPage();app.innerHTML=shell(body);if(page==='explore')loadRemoteCatalog();if(page==='catalogAdmin')loadAdminCareerCatalog();if(activeSession){const logout=document.createElement('button');logout.className='btn outline small';logout.dataset.action='signout';logout.textContent='Sign out';document.querySelector('.user-menu')?.prepend(logout)}}
app.addEventListener('click',async e=>{const b=e.target.closest('button[data-action="signout"]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();try{if(activeSession?.access_token){const response=await fetch(`${apiBase}/auth/signout`,{method:'POST',headers:{Authorization:`Bearer ${activeSession.access_token}`}});if(!response.ok)throw new Error('revocation failed')}activeSession=null;activeRoles=[];admin=false;page='landing';render();toast('Signed out. Session revocation confirmed.')}catch{toast('Sign-out could not be confirmed. Check the API and retry.')}});
app.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.catalogPage){catalogPage=Number(b.dataset.catalogPage);catalogRequestKey='';render();scrollTo(0,0)}if(b.dataset.go){if(['about','contact'].includes(b.dataset.go)){if(page!=='landing'){page='landing';render()}document.getElementById(b.dataset.go)?.scrollIntoView({behavior:'smooth'})}else{page=b.dataset.go;render();scrollTo(0,0)}}if(b.dataset.page){page=b.dataset.page;if(!admin&&['users','reports','settings'].includes(page))admin=true;render();scrollTo(0,0)}if(b.dataset.filter){pathFilter=b.dataset.filter;catalogPage=1;catalogRequestKey='';render()}if(b.dataset.action==='menu')document.querySelector('#sidebar')?.classList.toggle('open');if(b.dataset.action==='switch-role'){admin=!admin;page='home';render()}if(b.dataset.action==='career'){selectedCareer=b.dataset.name||'Cybersecurity';page='path';render();scrollTo(0,0)}if(b.dataset.action==='reload-admin-catalog')loadAdminCareerCatalog();if(b.dataset.action==='edit-catalog-career'){const item=adminCareerRows.find(c=>c.slug===b.dataset.slug),dialog=document.querySelector('#career-editor');if(item&&dialog){const form=dialog.querySelector('form');for(const name of ['slug','title','category','minimum_education','summary'])form.elements[name].value=item[name]||'';for(const [name,value] of [['entry_stages',item.entry_stages],['eligible_streams',item.eligible_streams],['skills',item.skills],['typical_roles',item.typical_roles]])form.elements[name].value=(value||[]).join(', ');dialog.showModal()}}if(b.dataset.action==='verify-catalog-career'){const dialog=document.querySelector('#career-verifier');if(dialog){dialog.querySelector('[name=slug]').value=b.dataset.slug;dialog.showModal()}}if(b.dataset.action==='deactivate-catalog-career'){if(!activeSession?.access_token)return toast('Sign in with a content-editor or admin role.');try{const response=await fetch(`${apiBase}/admin/career-catalog/${encodeURIComponent(b.dataset.slug)}`,{method:'PATCH',headers:{Authorization:`Bearer ${activeSession.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({is_active:false})});if(!response.ok)throw new Error((await response.json()).detail||'Deactivate action failed.');toast('Career deactivated.');loadAdminCareerCatalog()}catch(error){toast(error instanceof Error?error.message:'Career could not be deactivated.')}}if(b.dataset.action==='save-path'){localStorage.setItem('nd-saved',localStorage.getItem('nd-saved')?'':'yes');toast(localStorage.getItem('nd-saved')?'Pathway saved on this device.':'Pathway removed from saved items.');render()}if(b.dataset.action==='account'){toast('This is a local demo. No account is signed in.')}if(b.dataset.action==='review')toast('Demo review opened. Connect an authorized review service to publish changes.');if(b.dataset.action==='add')toast('Demo only: content changes require a connected, authorized backend.');if(b.dataset.action==='edit')toast('Profile editing is available in the demo form soon.');if(b.dataset.action==='details')toast('Check the official provider for current details.');let role=b.closest('.role-options')&&b;if(role){role.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));role.classList.add('selected')}});
app.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='node'||b.dataset.action==='tree-node'){toast(`${b.dataset.name}: choose a listed career or compare another branch in the pathway map.`)}if(b.dataset.action==='run-backtest'){const start=document.querySelector('#backtest-start')?.value,interest=document.querySelector('#backtest-interest')?.value||'Not sure yet';const choices=interest.includes('Technology')?['Science → Intermediate → Engineering → Software, cybersecurity, or data careers','Vocational → IT diploma → Apprenticeship → Technical support or network operations','Commerce → Business analytics → Data and operations roles']:interest.includes('Health')?['Science → Intermediate → Health sciences → Clinical or allied health study','Science → Research foundation → Life sciences and laboratory careers','Vocational → Healthcare skills → Technician training']:interest.includes('Business')?['Commerce → Degree or professional course → Finance, accounting, or operations','Science → Statistics and analytics → Business intelligence roles','Vocational → Retail or finance apprenticeship → Entry level operations']:interest.includes('Creative')?['Arts → Design foundation → Visual, interaction, or communication design','Science → Technology degree → Product design or creative technology','Vocational → Portfolio program → Media and production roles']:['Science → Technology or research','Commerce → Business, finance, or analytics','Arts → Design, communication, or humanities','Vocational → Diploma or apprenticeship'];document.querySelector('#backtest-result').innerHTML=`<h2>${start} · ${interest}</h2><p class="muted">${choices.length} possible routes · illustrative planning only</p><ol>${choices.map(x=>`<li>${x}</li>`).join('')}</ol><p class="muted">This simulation does not use historical outcome data. Confirm program availability and entry requirements with official institutions.</p>`}if(b.dataset.action==='run-debug'){const out=document.querySelector('#debug-result');out.innerHTML='<p>Checking API and configured service connections…</p>';try{const response=await fetch(`${apiBase}/diagnostics`,{headers:activeSession?.access_token?{Authorization:`Bearer ${activeSession.access_token}`}:{}});const data=await response.json();if(!response.ok)throw new Error(data.detail||'Diagnostics request failed.');out.innerHTML=`<div class="diagnostic-row"><b>API</b><span class="pill">Reachable</span></div><div class="diagnostic-row"><b>Supabase</b><span class="${data.supabase.status==='connected'?'pill':'status'}">${data.supabase.status}</span></div><div class="diagnostic-row"><b>NVIDIA NIM</b><span class="${data.nvidia.status==='configured'?'pill':'status'}">${data.nvidia.status}</span></div><p class="muted">${data.supabase.detail} ${data.nvidia.detail}</p>`}catch(err){out.innerHTML=`<p class="status">Unreachable</p><p>${err instanceof Error?err.message:'Diagnostics request failed.'}</p>`}}});
app.addEventListener('click',e=>{const b=e.target.closest('button[data-go]');if(!b||!['backtest','debug'].includes(b.dataset.go))return;page=b.dataset.go;render();scrollTo(0,0)});
app.addEventListener('change',e=>{if(e.target.matches('[data-item]')){let x=e.target.dataset.item;completed=e.target.checked?[...new Set([...completed,x])]:completed.filter(y=>y!==x);localStorage.setItem('nd-completed',JSON.stringify(completed));toast(e.target.checked?'Progress saved on this device.':'Progress updated.')}});
app.addEventListener('input',e=>{if(e.target.id==='global-search'||e.target.id==='career-search'){search=e.target.value;if(page!=='explore'){page='explore';render();let i=document.querySelector('#career-search');i?.focus();i?.setSelectionRange(i.value.length,i.value.length)}else{let q=search.toLowerCase();document.querySelectorAll('.pathway,.career-card').forEach(card=>card.classList.toggle('hidden',!card.textContent.toLowerCase().includes(q)));clearTimeout(catalogDebounceTimer);catalogDebounceTimer=setTimeout(()=>{catalogPage=1;catalogRequestKey='';loadRemoteCatalog()},300)}}});
app.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();if(!apiBase)return;e.stopImmediatePropagation();const form=e.target;const fields=[...form.querySelectorAll('input')];const email=fields.find(x=>x.type==='email')?.value;const password=fields.find(x=>x.type==='password')?.value;const request=async(path,body)=>fetch(`${apiBase}${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});try{if(page==='signin'){const response=await request('/auth/signin',{email,password});const data=await response.json();if(!response.ok)throw new Error(data.detail||'Sign in could not be completed.');activeSession=data;admin=false;activeRoles=[];try{const profile=await fetch(`${apiBase}/me`,{headers:{Authorization:`Bearer ${data.access_token}`}});if(profile.ok){const identity=await profile.json();activeRoles=identity.roles||[]}}catch{}admin=activeRoles.some(role=>['content_editor','verifier','admin'].includes(role));page='home';render();toast('Signed in successfully.')}else if(page==='signup'){const name=fields.find(x=>x.autocomplete==='name')?.value;const role=form.querySelector('.role-options .selected')?.textContent.trim().toLowerCase()||'student';const response=await request('/auth/signup',{email,password,full_name:name,role});const data=await response.json();if(!response.ok)throw new Error(data.detail||'Sign-up could not be completed.');page='signin';render();toast(data.confirmation_required?'Check your inbox to confirm the account, then sign in.':'Account created. Sign in to continue.')}else if(page==='forgot'){const response=await request('/auth/forgot-password',{email});const data=await response.json();if(!response.ok)throw new Error(data.detail||'Reset request could not be completed.');toast(data.message||'If an account matches, reset instructions will be sent.')}else if(page==='reset'){const confirm=fields[1]?.value;if(password!==confirm)throw new Error('The passwords do not match.');const tokens=new URLSearchParams(location.hash.slice(1));const response=await request('/auth/reset-password',{access_token:tokens.get('access_token'),refresh_token:tokens.get('refresh_token'),password});if(!response.ok)throw new Error('Password reset link is invalid or expired. Request a new link and try again.');history.replaceState(null,'',location.pathname);activeSession=null;page='signin';render();toast('Password updated. Sign in with the new password.')} }catch(error){toast(error instanceof Error?error.message:'Could not reach the guidance service. Start the API and try again.')}});
app.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.action==='run-backtest'){const start=document.querySelector('#backtest-start')?.value||'Class 10';const interest=document.querySelector('#backtest-interest')?.value||'Not sure yet';const matches=pathwayEngine.select(pathways,{start,interest});const result=document.querySelector('#backtest-result');if(!result)return;if(!matches.length){result.innerHTML='<p class="status">No example route is currently listed for that stage and interest. Try “Not sure yet” or another stage.</p>';return}result.innerHTML=`<h2>${matches.length} example route${matches.length===1?'':'s'} from ${start}</h2><div class="path-map-scroll"><div class="path-graph-grid">${graphRows(matches)}</div></div><p class="muted">Interest filter: ${interest}. Routes are scenario examples, not historical backtests, admissions predictions, official eligibility decisions, or live opportunities.</p>`}if(button.dataset.action==='run-auth-checks'){const output=document.querySelector('#auth-debug-result');if(!output)return;if(!apiBase){output.innerHTML='<p class="status">Skipped: configure the frontend API URL first.</p>';return}output.innerHTML='<p class="muted">Running safe checks…</p>';const checks=[{name:'API health',path:'/health',method:'GET',expected:200},{name:'Protected profile rejects missing session',path:'/me',method:'GET',expected:401},{name:'Privileged self-signup is rejected',path:'/auth/signup',method:'POST',expected:403,body:{email:'probe@example.invalid',password:'not-a-real-password',full_name:'Safe diagnostic probe',role:'admin'}},{name:'Invalid sign-in request is rejected by validation',path:'/auth/signin',method:'POST',expected:422,body:{email:'',password:''}},{name:'Auth provider configuration endpoint',path:'/diagnostics/auth',method:'GET',expected:200}];const results=[];for(const check of checks){try{const response=await fetch(`${apiBase}${check.path}`,{method:check.method,headers:check.body?{'Content-Type':'application/json'}:undefined,body:check.body?JSON.stringify(check.body):undefined,cache:'no-store'});let detail='';if(check.path==='/diagnostics/auth'&&response.ok){const state=await response.json();detail=` · ${state.status}; live account flows tested: ${state.live_account_flows_tested?'yes':'no'}`}results.push({name:check.name,passed:response.status===check.expected,detail:response.status===check.expected?'':` · expected ${check.expected}, received ${response.status}`})}catch{results.push({name:check.name,passed:false,detail:' · API unreachable'})}}output.innerHTML=`<div class="diagnostic-list">${results.map(result=>`<div class="diagnostic-row"><b>${result.name}</b><span class="${result.passed?'pill':'status'}">${result.passed?'PASS':'FAIL'}${result.detail}</span></div>`).join('')}</div><p class="muted">These probes do not create users or change database rows. They do not verify live password, email recovery, refresh, or role-grant flows.</p>`}});
render();

app.addEventListener('submit',e=>{if(e.target.id==='auth-form'&&!apiBase){e.preventDefault();e.stopImmediatePropagation();toast('Authentication is unavailable: configure NEXT_PUBLIC_API_BASE_URL and start the API.')}},true);


app.addEventListener('submit',async e=>{const form=e.target;if(!['catalog-add-form','catalog-edit-form','catalog-verify-form'].includes(form.id))return;e.preventDefault();if(!activeSession?.access_token)return toast('Staff sign-in is required.');const status=form.querySelector('[data-form-status]');if(status)status.textContent='Saving…';try{let url,method='POST',body,data;if(form.id==='catalog-add-form'){data=formCareer(form);const rawSlug=String(new FormData(form).get('slug')||data.title).toLowerCase();data.slug=rawSlug.normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');data.sources=[];url=`${apiBase}/admin/career-catalog`}else if(form.id==='catalog-edit-form'){const data=formCareer(form);const fields=new FormData(form);data.slug=undefined;url=`${apiBase}/admin/career-catalog/${encodeURIComponent(fields.get('slug'))}`;method='PATCH';body=data}else{const fields=new FormData(form);url=`${apiBase}/admin/career-catalog/${encodeURIComponent(fields.get('slug'))}/verify`;body={verified_at:new Date().toISOString(),sources:[{name:String(fields.get('source_name')).trim(),url:String(fields.get('source_url')).trim(),note:'Checked by an authorized Next Dreams verifier.'}]}}if(form.id==='catalog-add-form')body=data;const response=await fetch(url,{method,headers:{Authorization:`Bearer ${activeSession.access_token}`,'Content-Type':'application/json'},body:JSON.stringify(body)});if(!response.ok)throw new Error((await response.json()).detail||'Catalog change was rejected.');if(form.id==='catalog-edit-form'||form.id==='catalog-verify-form')form.closest('dialog').close();form.reset();if(status)status.textContent='Draft saved. It remains labelled for source review.';toast(form.id==='catalog-verify-form'?'Verification recorded.':'Career catalog saved.');await loadAdminCareerCatalog()}catch(error){const message=error instanceof Error?error.message:'Catalog update failed.';if(status)status.textContent=message;else toast(message)}});

